package com.sahibex.companion;

import android.accessibilityservice.AccessibilityService; import android.accessibilityservice.GestureDescription; import android.graphics.Bitmap; import android.graphics.Path; import android.graphics.Rect; import android.hardware.HardwareBuffer; import android.os.Bundle; import android.view.Display; import android.view.KeyEvent; import android.view.accessibility.AccessibilityNodeInfo; import java.io.ByteArrayOutputStream; import java.util.Base64; import java.util.concurrent.CountDownLatch; import java.util.concurrent.TimeUnit; import java.util.concurrent.atomic.AtomicReference; import org.json.JSONArray; import org.json.JSONObject;

public final class SahibexAccessibilityService extends AccessibilityService {
 private BridgeServer server;
 @Override protected void onServiceConnected(){super.onServiceConnected();server=new BridgeServer(this,38741);server.start();}
 @Override public void onDestroy(){if(server!=null)server.stop();super.onDestroy();}
 String getSharedToken(){return getSharedPreferences("sahibex",MODE_PRIVATE).getString("token",null);}
 JSONObject handle(String action,JSONObject p)throws Exception{if(p==null)p=new JSONObject();switch(action){case "tap":tap(p.getInt("x"),p.getInt("y"));return new JSONObject().put("accepted",true);case "swipe":swipe(p.getInt("x"),p.getInt("y"),p.getInt("end_x"),p.getInt("end_y"),p.optLong("duration_ms",100));return new JSONObject().put("accepted",true);case "type_text":return typeText(p.getString("text"));case "keyevent":return globalKey(p.getInt("keycode"));case "ui_tree":return new JSONObject().put("tree",tree(getRootInActiveWindow(),0));case "screenshot":return screenshot();default:throw new IllegalArgumentException("unsupported action: "+action);}}
 private void tap(int x,int y){Path p=new Path();p.moveTo(x,y);GestureDescription.StrokeDescription s=new GestureDescription.StrokeDescription(p,0,80);dispatchGesture(new GestureDescription.Builder().addStroke(s).build(),null,null);}
 private void swipe(int x,int y,int ex,int ey,long ms){Path p=new Path();p.moveTo(x,y);p.lineTo(ex,ey);GestureDescription.StrokeDescription s=new GestureDescription.StrokeDescription(p,0,Math.max(1,ms));dispatchGesture(new GestureDescription.Builder().addStroke(s).build(),null,null);}
 private JSONObject typeText(String text){AccessibilityNodeInfo n=findEditable(getRootInActiveWindow());if(n==null)throw new IllegalStateException("no focused editable node");Bundle b=new Bundle();b.putCharSequence(AccessibilityNodeInfo.ACTION_ARGUMENT_SET_TEXT_CHARSEQUENCE,text);return new JSONObject().put("accepted",n.performAction(AccessibilityNodeInfo.ACTION_SET_TEXT,b));}
 private JSONObject globalKey(int k){boolean ok;if(k==KeyEvent.KEYCODE_BACK)ok=performGlobalAction(GLOBAL_ACTION_BACK);else if(k==KeyEvent.KEYCODE_HOME)ok=performGlobalAction(GLOBAL_ACTION_HOME);else if(k==KeyEvent.KEYCODE_RECENTS)ok=performGlobalAction(GLOBAL_ACTION_RECENTS);else throw new IllegalArgumentException("unsupported global key");return new JSONObject().put("accepted",ok);}
 private AccessibilityNodeInfo findEditable(AccessibilityNodeInfo n){if(n==null)return null;if(n.isEditable()&&n.isFocused())return n;for(int i=0;i<n.getChildCount();i++){AccessibilityNodeInfo x=findEditable(n.getChild(i));if(x!=null)return x;}return null;}
 private JSONArray tree(AccessibilityNodeInfo n,int depth){JSONArray a=new JSONArray();if(n==null||depth>12)return a;JSONObject o=new JSONObject();Rect r=new Rect();n.getBoundsInScreen(r);o.put("class",String.valueOf(n.getClassName()));o.put("text",n.getText());o.put("contentDescription",n.getContentDescription());o.put("clickable",n.isClickable());o.put("editable",n.isEditable());o.put("enabled",n.isEnabled());o.put("bounds",new JSONArray().put(r.left).put(r.top).put(r.right).put(r.bottom));JSONArray c=new JSONArray();for(int i=0;i<n.getChildCount();i++){JSONArray q=tree(n.getChild(i),depth+1);for(int j=0;j<q.length();j++)c.put(q.get(j));}o.put("children",c);a.put(o);return a;}
 private JSONObject screenshot()throws Exception{if(android.os.Build.VERSION.SDK_INT<30)throw new IllegalStateException("screenshot requires Android 11+");CountDownLatch latch=new CountDownLatch(1);AtomicReference<Bitmap> ref=new AtomicReference<>();AtomicReference<Throwable> err=new AtomicReference<>();takeScreenshot(Display.DEFAULT_DISPLAY,getMainExecutor(),new TakeScreenshotCallback(){@Override public void onSuccess(ScreenshotResult r){try{HardwareBuffer h=r.getHardwareBuffer();Bitmap b=Bitmap.wrapHardwareBuffer(h,r.getColorSpace());if(b==null)throw new IllegalStateException("bitmap conversion failed");ref.set(b);h.close();}catch(Throwable t){err.set(t);}finally{latch.countDown();}}@Override public void onFailure(int e){err.set(new IllegalStateException("screenshot failed: "+e));latch.countDown();}});if(!latch.await(5,TimeUnit.SECONDS))throw new IllegalStateException("screenshot timeout");if(err.get()!=null)throw new IllegalStateException(err.get().toString());Bitmap b=ref.get();ByteArrayOutputStream out=new ByteArrayOutputStream();b.compress(Bitmap.CompressFormat.PNG,100,out);byte[] data=out.toByteArray();return new JSONObject().put("bytes",data.length).put("sha256",sha256(data)).put("base64",Base64.getEncoder().encodeToString(data));}
 private String sha256(byte[] b)throws Exception{java.security.MessageDigest d=java.security.MessageDigest.getInstance("SHA-256");byte[] x=d.digest(b);StringBuilder s=new StringBuilder();for(byte q:x)s.append(String.format("%02x",q));return s.toString();}
}
